def plan(N,h,w,start,a,b,block=None,maxit=30):
    cur=start; got=orbit_bits(N,h,w,a,b,*cur); moves=[]
    for it in range(maxit):
        if got==Ybits: return moves,0
        best=None
        for r0 in range(0,64-h,1):
            for c0 in range(0,62-w,1):
                if (r0-start[0])%3 or (c0-start[1])%3: continue
                if block and any(0<=r<63 and 0<=c<62 and ((r*62+c) in block) for r in range(r0,r0+h) for c in range(c0,c0+w)): pass
                d=abs(r0-cur[0])//3+abs(c0-cur[1])//3
                if d==0: continue
                # coverage along L path (row first then col)
                m=0; rr,cc=cur
                for i in range(cur[0],r0,3 if r0>cur[0] else -3):
                    m|=orbit_bits(N,h,w,a,b,i,cc)
                for i in range(cc,c0,3 if c0>cc else -3):
                    m|=orbit_bits(N,h,w,a,b,r0,i)
                m|=orbit_bits(N,h,w,a,b,r0,c0)
                new=bin(m&~got).count('1')
                if new==0: continue
                sc=new/(1+d)
                if best is None or sc>best[0]: best=(sc,(r0,c0),new,d,m)
        if best is None: return moves,bin(Ybits&~got).count('1')
        sc,pos,new,d,m=best
        # record moves
        dr=pos[0]-cur[0]; dc=pos[1]-cur[1]
        if dr: moves.append((('DOWN' if dr>0 else 'UP'),abs(dr)//3))
